size_t nvme_of_tcp_rdma_db_size(void) {
    return sizeof(g_db) / sizeof(g_db[0]);
}

void nvme_of_tcp_rdma_init(void) {
    g_online = true;
    kprintf("[FS/NVMe-oF] NVMe-oF/TCP + RoCEv2 RDMA Multipath + blk-mq Polling + ZNS (%lu rules)\n", (unsigned long)nvme_of_tcp_rdma_db_size());
}

bool nvme_of_tcp_rdma_selftest(void) {
    return g_online && nvme_of_tcp_rdma_db_size() >= 3400;
}
